// shortcut: an image replaced under the same name keeps its old copy offline; rename the file (or bump IMG) when one changes
const CACHE = 'fw-' + VERSION, IMG = 'fw-img';

self.addEventListener('install', e => {
  // one by one with retries: a busy local server may drop a connection; reload skips the HTTP cache
  e.waitUntil(caches.open(CACHE).then(async c => {
    for (const u of PRECACHE) {
      for (let n = 0; ; n++) {
        try { await c.add(new Request(u, { cache: 'reload' })); break; } catch (err) { if (n >= 2) throw err; await new Promise(r => setTimeout(r, 300 * (n + 1))); }
      }
    }
  }).then(() => caches.open(IMG)).then(async c => {
    // images: only the missing ones, a few at a time; one that fails is fetched again when a page shows it
    const have = new Set((await c.keys()).map(r => new URL(r.url).pathname));
    const todo = (typeof IMAGES === 'undefined' ? [] : IMAGES).filter(u => !have.has(new URL(u, self.registration.scope).pathname));
    const one = async () => { for (let u; (u = todo.shift());) await c.add(u).catch(() => {}); };
    await Promise.all(Array.from({ length: 6 }, one));
  }));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k.startsWith('fw-') && k !== CACHE && k !== IMG).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('message', e => { if (e.data === 'skip-waiting') self.skipWaiting(); });

const isIndex = u => { const p = u.href.split(/[?#]/)[0]; return p === self.registration.scope || p === self.registration.scope + 'index.html'; };

self.addEventListener('fetch', e => {
  const r = e.request, u = new URL(r.url);
  if (r.method !== 'GET' || u.origin !== location.origin) return;
  if (r.mode === 'navigate' && !isIndex(u)) return;  // the static pages (p/, en/p/) are their own documents, never the app shell
  if (isIndex(u)) {
    e.respondWith(fetch(r).then(res => {
      if (res.ok && isIndex(u)) { const copy = res.clone(); caches.open(CACHE).then(c => c.put('./', copy)); }
      return res;
    }).catch(() => caches.match('./', { cacheName: CACHE }).then(hit => hit || caches.match('./'))));
    return;
  }
  e.respondWith(caches.match(r).then(hit => hit || fetch(r).then(res => {
    const store = res.ok && (u.searchParams.has('v') || /_textos(_en)?\.data\.js$/.test(u.pathname) ? CACHE : u.pathname.includes('/img/') ? IMG : null);
    if (store) { const copy = res.clone(); caches.open(store).then(c => c.put(r, copy)); }
    return res;
  })));
});
